// macOS 14 Dock gesture event layout. Field names cross-checked with WebKit
// CoreGraphicsTestSPI and Mac Mouse Fix TouchSimulator (Noah Nuebling).
// No keyboard events are generated by this module.
static double dockProgress=0,dockDelta=0,dockRepeatAt=0;
static int dockAxis=0,dockRepeat=0;
static void dockPost(int phase){
 CGEventRef event=CGEventCreate(NULL), companion=CGEventCreate(NULL);
 CGEventSetType(event,(CGEventType)30);CGEventSetType(companion,(CGEventType)29);
 CGEventSetDoubleValueField(event,(CGEventField)41,33231);
 CGEventSetDoubleValueField(companion,(CGEventField)41,33231);
 CGEventSetIntegerValueField(event,(CGEventField)110,23);
 CGEventSetIntegerValueField(event,(CGEventField)123,dockAxis);
 CGEventSetIntegerValueField(event,(CGEventField)165,dockAxis);
 CGEventSetIntegerValueField(event,(CGEventField)132,phase);
 CGEventSetIntegerValueField(event,(CGEventField)134,phase);
 CGEventSetDoubleValueField(event,(CGEventField)124,dockProgress);
 float fp=(float)dockProgress,axisBits;uint32_t bits,axis=(uint32_t)dockAxis;
 memcpy(&bits,&fp,sizeof(bits));memcpy(&axisBits,&axis,sizeof(axisBits));
 CGEventSetIntegerValueField(event,(CGEventField)135,bits);
 CGEventSetDoubleValueField(event,(CGEventField)119,(double)axisBits);
 CGEventSetDoubleValueField(event,(CGEventField)139,(double)axisBits);
 CGEventSetIntegerValueField(event,(CGEventField)136,0);
 if(phase==4){CGEventSetDoubleValueField(event,(CGEventField)129,dockDelta*100);CGEventSetDoubleValueField(event,(CGEventField)130,dockDelta*100);}
 CGEventPost(kCGSessionEventTap,event);CGEventPost(kCGSessionEventTap,companion);
 CFRelease(event);CFRelease(companion);
}
static void dockBegin(int axis){dockAxis=axis;dockRepeat=0;dockProgress=dockDelta=0;dockPost(1);}
static void dockMove(double delta){if(fabs(delta)<0.000001)return;dockDelta=delta;dockProgress+=delta;dockPost(2);}
static void dockEnd(void){dockPost(4);dockRepeat=1;dockRepeatAt=CFAbsoluteTimeGetCurrent()+.2;}
static void dockTick(void){if(dockRepeat&&CFAbsoluteTimeGetCurrent()>=dockRepeatAt){dockPost(4);if(dockRepeat==1){dockRepeat=2;dockRepeatAt=CFAbsoluteTimeGetCurrent()+.3;}else dockRepeat=0;}}
